کدوم پیام رو می‌خوای تنظیم کنی؟

📌 این‌ها همه‌ی متن‌هایی هستن که کاربر موقع تخفیف شارژ کیف پول می‌بینه - از صفحه‌ی وارد کردن کد تا جمله‌ای که مقدار تخفیف رو اعلام می‌کنه.

<blockquote>💡 این متن‌ها بین <b>همه‌ی درگاه‌ها</b> مشترکن - هر تغییری اینجا بدی، روی همه‌ی درگاه‌ها اعمال می‌شه.

خودِ تخفیف (درصد، مبلغ، مدت، سهمیه، و اینکه روی همه‌ی مبلغ‌ها اعمال بشه یا فقط روی بسته‌های آماده) برای هر درگاه و هر دسته جداست و از این مسیر تنظیم می‌شه:

🏬 تنظیمات فروشگاه ← 🏦 بسته‌های شارژ ← 🎁 تخفیف شارژ</blockquote>

✅ رنگ سبز دکمه یعنی متن اون از قبل ست شده.',
    'groupCvolCaption' => '🧩 <b>حجم دلخواه</b> — {lang}

کدوم مورد رو می‌خوای تنظیم کنی؟

📱 <b>صفحه‌ی ساخت</b>: کپشن، دکمه‌ها (ادامه، وارد کردن عدد، بازگشت، ...) و استیکرش.
♻️ <b>صفحه‌ی تمدید</b>: همون صفحه، وقتی سرویسی که با حجم دلخواه خریده شده تمدید می‌شه.
🧱 <b>تکه‌های متن</b>: خط‌های کوچیک توی کپشن (تخفیف، کمبود موجودی، واحدها، ...) و پاپ‌آپ‌ها.

⚙️ قیمت‌ها، گام‌ها (−/+)، حالت انتخاب و فیلترها از «تنظیمات خود قابلیت» پایین تنظیم می‌شن.

✅ رنگ سبز دکمه یعنی اون مورد از قبل تغییر کرده.',
    'groupCvolPiecesCaption' => '🧱 <b>تکه‌های متن حجم دلخواه</b> — {lang}

خط‌های کوچیکی که توی کپشن صفحه‌ی حجم دلخواه میان و پاپ‌آپ‌هاش. هر کدوم متن و ایموجی پریمیوم خودش رو داره؛ جای عددها با <code>{n}</code> و ... پر می‌شه، پس وقتی عوضشون می‌کنی همین علامت‌ها رو نگه دار.

✅ رنگ سبز دکمه یعنی اون مورد از قبل تغییر کرده.',
    'groupMsMoreCaption' => '🛍 <b>پیام‌های کارهای روی سرویس</b>

کدوم مورد رو می‌خوای تنظیم کنی؟

📌 پیام‌هایی که بعد از زدن دکمه‌های صفحه‌ی سرویس به مشتری می‌رسه: تمدید، حجم و زمان اضافه، تغییر لینک، انتقال، تغییر لوکیشن، یادداشت، حذف سرویس، روشن/خاموش، گزارش اختلال و جستجوی سرویس. متن، استیکر و ایموجی پریمیوم هر کدوم برای هر زبان جداست.

✅ رنگ سبز دکمه یعنی متن یا استیکر اون از قبل ست شده.',
    'groupMiscCaption' => '☎️ <b>پشتیبانی، کد هدیه و پیام‌های دیگر</b>

کدوم مورد رو می‌خوای تنظیم کنی؟

📌 پیام‌های بخش پشتیبانی، کد هدیه، درخواست نمایندگی، دانلود برنامه، عضویت کانال و بلاک، و پیام‌های خطای عمومی ربات. متن، استیکر و ایموجی پریمیوم هر کدوم برای هر زبان جداست.

✅ رنگ سبز دکمه یعنی متن یا استیکر اون از قبل ست شده.',
    'groupAccountCaption' => '👤 <b>حساب کاربری</b>

کدوم مورد رو می‌خوای تنظیم کنی؟

📌 این همون صفحه‌ایه که کاربر با زدن دکمه‌ی «👤 حساب کاربری» می‌بینه - نام کاربری، آیدی، تعداد سرویس و موجودیش.

📌 دکمه‌ی ❌ بستنِ همین صفحه هم اینجاست: متن و رنگش جدا از بقیه‌ی بخش‌هاست، پس هرچی اینجا بذاری فقط روی همین صفحه اثر داره.

✅ رنگ سبز دکمه یعنی متن یا استیکر اون از قبل ست شده.',
    'groupHelpCaption' => '📚 <b>پیام و دکمه‌های آموزش</b>

کدوم مورد رو می‌خوای تنظیم کنی؟

📌 بخش آموزش دو تا صفحه داره: اول لیست دسته‌بندی‌ها (اگه دسته‌بندی آموزش روشن باشه)، بعد لیست خود آموزش‌ها. هرکدوم کپشن جدا خودشو داره.

📌 خودِ آموزش‌ها (اضافه‌کردن، ویرایش، حذف) اینجا نیستن - از دکمه‌ی 📚 آموزش توی پنل ادمین مدیریت می‌شن. اینجا فقط متن و ظاهرشونه.

<blockquote>💡 دو دکمه‌ی پایین (زیر تیتر 🎨) همون صفحه‌های تنظیم ظاهرن که از مسیر 📚 آموزش ← 🎨 نمایش هم باز می‌شن؛ برای همین دکمه‌ی بازگشتشون به منوی آموزش برمی‌گرده، نه به اینجا.</blockquote>

✅ رنگ سبز دکمه یعنی متن یا استیکر اون از قبل ست شده.',
    'backToListLabel' => '🔙 برگشت به لیست',
    'resetAllDone' => '🔁 همه متن‌ها، استیکرها و ری‌اکشن‌های این بخش (توی همه زبون‌ها) به حالت پیش‌فرض ربات برگشتن.',
    'home_text' => '🎨 <b>شخصی‌سازی پیام‌های ربات</b>

متنی که می‌خواهی تغییر دهی را انتخاب کن.

⬜️ دکمه‌های سفید فقط تیتر بخش‌ان (کاربردشون از هم جداست)؛ خودشون قابل لمس نیستن، فقط با یه پیام کوتاه توضیح می‌دن اون بخش چیه.

🟢 دکمه سبز یعنی این مورد سفارشی شده:
✏️ متنش عوض شده   ❤️ ری‌اکشن دارد   🖼 استیکر دارد   🔘 دکمه‌هایش عوض شده

📌 این‌ها فقط پیام‌های داخل مراحل مختلفن؛ برای استیکر و ظاهر لحظه‌ی لمس دکمه‌های منوی اصلی، از 🔘 تنظیمات دکمه‌های منوی اصلی همین پایین استفاده کن.

