      'appTitle' => "🔗 <b>لینک دانلود برنامه</b> — {lang}\n\nاین لیست مخصوص همین زبانه.{list}\n\n✏️ برای ویرایش لینک، 🗑 برای حذف. 🌍 یعنی برای همه‌ی زبان‌هاست؛ ویرایش یا حذفش از این تب فقط روی همین زبان اثر می‌ذاره.",
