      'wheelTitle' => "🎲 <b>تنظیمات گردونه شانس</b> — {lang}\n\nمبلغ برد: <b>{price}</b>\n\nاین مبلغ فقط برای همین زبان اعمال می‌شه.",
      'wheelPriceBtn' => '💰 مبلغ برد: {price}',
      'affTitle' => "👥 <b>طرح‌های زیرمجموعه‌گیری</b> — {lang}\n\n💼 زیرمجموعه‌گیری و هدیه خوش‌آمد: <b>{classic}</b>\n🎁 کانفیگ رایگان با دعوت: <b>{reward}</b>\n\nروی هر طرح بزن تا صفحه‌ی خودش باز بشه. هر طرح روشن/خاموش خودش رو داره (پیش‌فرض هر دو خاموش) و همه‌ی تنظیمات فقط برای زبان {lang}ه.\n📌 اگه هر دو خاموش باشن و کاربر دکمه‌ی زیرمجموعه‌گیری رو بزنه، پیام «هیچ طرحی فعال نیست» رو می‌گیره.\n🎨 متن پیام‌ها: 🎨 شخصی‌سازی پیام‌های ربات ← 🎁 پیام و دکمه‌های زیرمجموعه‌گیری.\n\n🎨 رنگ دکمه‌ها توی این صفحه‌ها:\n🟢 روشن · 🔴 خاموش (یا حذف) · 🔵 تنظیم یه مقدار · ⚪️ رفتن به صفحه‌ی دیگه یا برگشت",
      'affcTitle' => "💼 <b>زیرمجموعه‌گیری و هدیه خوش‌آمد</b> — {lang}\nوضعیت: <b>{state}</b>\n\n📊 درصد پورسانت: <b>{percent}%</b>\n💵 پورسانت خرید: <b>{commission}</b> · 1️⃣ فقط اولین خرید: <b>{firstbuy}</b>\n🎁 مبلغ هدیه عضویت: <b>{gift}</b> · 🎉 هدیه عضویت: <b>{startgift}</b>\n🖼 بنر: {banner}\n🛡 راستی‌آزمایی دعوت‌ها: <b>{refv}</b>\n\n• 💵 پورسانت خرید: از هر خرید زیرمجموعه، این درصد به معرف می‌رسه (با «1️⃣ فقط اولین خرید»، فقط از خرید اولش).\n• 🎉 هدیه عضویت: کاربر دعوت‌شده با دکمه‌ی «دریافت هدیه» این مبلغ رو می‌گیره - نصفش برای خودش، نصفش برای معرف.\n• تا این طرح خاموشه، نه هدیه عضویت داده می‌شه نه پورسانت.\n• 👁 با «پیش‌نمایش پیام‌ها» می‌بینی کاربرها دقیقاً چی می‌گیرن.",
      'affrTitle' => "🎁 <b>کانفیگ رایگان با دعوت</b> — {lang}\nوضعیت: <b>{state}</b>\n\nکاربری که <b>{need}</b> نفر رو با لینک خودش بیاره، یه کانفیگ <b>{volume} گیگ · {days} روزه</b> می‌گیره - هر کاربر تا <b>{max}</b> بار؛ بعد از هر بار، شمارنده‌ش از صفر شروع می‌شه.\n🖥 پنل: <b>{panel}</b> · 📨 تحویل: <b>{mode}</b>\n🚪 غیرفعال شدن با خروج از کانال: <b>{leave}</b>\n🛡 راستی‌آزمایی دعوت‌ها: <b>{refv}</b>\n\n• فقط کسایی حساب می‌شن که بعد از روشن کردنش عضو ربات شدن.\n• با تایید ادمین: درخواست با لیست دعوت‌شده‌ها برای ادمین‌ها میاد؛ اگه رد بشه، دعوت‌ها از صفر شمرده می‌شن. خودکار: همون لحظه ساخته می‌شه (اگه پنل خطا بده، برای تایید میاد).\n• 🚪 اگه روشن باشه و یکی از کسایی که کانفیگ به‌خاطرشون داده شده از کانال‌های 📯 راستی‌آزمایی همین طرح خارج بشه و تعداد کم بیاد، کانفیگ موقتاً غیرفعال می‌شه و به کاربر پیام می‌ره؛ با دعوت نفر جدید یا برگشتن طرف، خودکار دوباره روشن می‌شه. ربات باید توی اون کانال‌ها ادمین باشه.\n• 🔒 کسی که به سقف «🔁 چند بار» رسیده، با زدن «👥 زیرمجموعه‌گیری» پیام «سقف کانفیگ رایگانت پر شده» رو می‌گیره.\n• 🔄 «صفر کردن دعوت‌های یک کاربر»: با آیدی، دعوت‌ها و دفعه‌هایی که کانفیگ گرفته صفر می‌شه تا دوباره بتونه دعوت کنه و کانفیگ بگیره.\n• 🛡 ادمین بدون محدودیت (هر بار «👥 زیرمجموعه‌گیری» رو بزنه کانفیگ می‌گیره، بدون دعوت، تا سقف «🔁 چند بار»؛ به سقف که رسید خودش خاموش می‌شه): از 🎨 شخصی‌سازی ← «🛡 دسترسی و محدودیت‌های ادمین» - برای همه‌ی زبان‌ها یکیه.\n• 🧪 با «تست کانفیگ رایگان» می‌بینی کاربر و ادمین دقیقاً چه پیام‌هایی می‌گیرن.",
      'refvTitle' => "🛡 <b>راستی‌آزمایی دعوت‌ها</b> — {lang}\n{plan}\n\nشرط‌ها: <b>{state}</b>\n👑 معرف‌های بدون شرط: <b>{vip}</b> نفر\n\n• تا کاربر دعوت‌شده این شرط‌ها رو انجام نده، دعوتش برای این طرح حساب نمی‌شه ({what}). ربات همون لحظه‌ی ورود ازش می‌خواد و تا اون موقع می‌تونه از ربات استفاده کنه.\n• تا این طرح خاموشه، شرطی نمی‌خواد.\n• 👑 دعوت‌های معرف‌های بدون شرط برای این طرح بدون راستی‌آزمایی حساب می‌شه{auto}.",
