      'hubCaption' => "💳 <b>پرداخت مستقیم</b> — {lang}\n\n<b>این قابلیت چیه؟</b>\nتوی صفحهٔ تایید، کنار «✅ تایید و پرداخت از کیف پول» یه دکمهٔ «💳 پرداخت مستقیم» هم میاد. مشتری با اون همون لحظه از یکی از درگاه‌ها پول سرویس رو می‌ده؛ بعد از پرداخت سرویس خودکار ساخته (یا تمدید) می‌شه و به موجودی کیف پولش دست نمی‌زنیم.\n\n<b>روی کدوم مسیرها کار کنه؟</b>\n🛍 خرید اشتراک: از «🔐 خرید اشتراک» تا «تایید و پرداخت»\n🧩 حجم دلخواه: صفحهٔ تایید خرید با حجم دلخواه\n♻️ تمدید: توی «🛍 سرویس‌های من» ← تمدید ← فاکتور تمدید\n\n<b>حداقل و حداکثر شارژ:</b>\nهر درگاه یه حداقل و حداکثر برای «افزایش موجودی» داره. پیش‌فرض اینجا <b>خاموشه</b>: پرداخت مستقیم به اون محدودیت‌ها کاری نداره و مشتری هر مبلغی که قیمت سرویسه رو می‌پردازه. اگه روشنش کنی، همون حداقل و حداکثرِ درگاه روی پرداخت مستقیم هم اعمال می‌شه و مشتری برای مبلغ بیرون از بازه پیغام «مبلغ باید بین ... باشه» می‌گیره.\n\n<b>🎁 هدیهٔ شارژ:</b>\nاگه برای یه درگاه «هدیهٔ شارژ» (تخفیف خودکار یا کد تخفیف) گذاشتی، مشتری موقع شارژ کیف پول هدیه می‌گیره. پیش‌فرض اینجا <b>خاموشه</b>: پرداخت مستقیم هدیه‌ای نمی‌ده و روی فاکتورش هم حرفی از هدیه نیست. اگه روشنش کنی همون قانون‌های شارژ (درگاه، حداقل مبلغ، تعداد دفعات، تاریخ انقضا، بسته‌های آماده، کدی که مشتری از قبل فعال کرده) روی پرداخت مستقیم هم اجرا می‌شه: هدیه توی فاکتور و بالای لیست درگاه‌ها نشون داده می‌شه و بعد از پرداخت به کیف پول مشتری اضافه می‌شه.\n\n🎨 اسم و رنگ و جای دکمه‌ها و متن این مرحله رو از دکمه‌های پایین عوض کن (هر زبان جدا).",
