      'volFixedOnly' => "📌 <b>حجم ثابت</b> — {panel}\n\nالان حالت انتخاب «📅 فقط مدت»ـه؛ یعنی مشتری حجم رو انتخاب نمی‌کنه و همه‌ی سرویس‌ها همین حجم رو دارن:\n\n📦 حجم ثابت: <b>{fixed}</b> گیگ\n\nقیمت هر سرویس = {fixed} × قیمت هر گیگ + روزی که مشتری انتخاب می‌کنه × قیمت هر روز.\n\n<i>می‌خوای مشتری خودش حجم رو انتخاب کنه؟ از «🎛 حالت انتخاب»، «📦📅 هر دو» رو بزن؛ اون‌وقت حداقل، حداکثر و گام ➖/➕ هم همین‌جا میاد.</i>",
