      'help' => "📖 <b>راهنمای حجم دلخواه</b>\n\n<b>چیه؟</b>\nمشتری به‌جای انتخاب بسته‌ی آماده، حجم و مدت سرویس رو خودش انتخاب می‌کنه. صفحه با دکمه‌های −/+ (گام‌هایی که تو می‌ذاری)، دکمه‌های عدد آماده یا تایپ عدد کار می‌کنه و قیمت همون لحظه توی کپشن عوض می‌شه. با «✅ ادامه»، خرید مثل یه بسته‌ی معمولی جلو می‌ره: نام سرویس، فاکتور، کد تخفیف و پرداخت.\n\n<b>کجا دیده می‌شه؟</b>\n• زیر لیست سرویس‌های همین پنل (دکمه‌ی «🧩 حجم دلخواه»)\n• اگه این پنل بسته‌ی آماده نداشته باشه، مستقیم همین صفحه باز می‌شه\n• خرید عمده (چند سرویس با هم)\n• تمدید سرویس‌هایی که با حجم دلخواه خریده شدن\n\n<b>قدم‌به‌قدم</b>\n1️⃣ «💰 قیمت‌ها»: برای هر زبان قیمت یک گیگ و یک روز رو بذار (هر زبان واحد پول خودش رو داره). برای نماینده‌ها خالی بذاری، قیمت کاربر عادی حساب می‌شه.\n2️⃣ «🎛 حالت انتخاب»: هر دو، فقط حجم (با مدت ثابت) یا فقط مدت (با حجم ثابت). «ثابت» یعنی عددی که برای همه یکسانه؛ دکمه‌اش زیر همون صفحه‌ست.\n3️⃣ «📦 تنظیم حجم» و «📅 تنظیم مدت»: حداقل، حداکثر، عدد شروع و دکمه‌های آماده. «👣 گام‌ها» هر کدوم یه جفت دکمه −/+ می‌سازه: تا ۳ گام (مثلاً ۱ و ۱۰) و هر گام رو می‌تونی عوض یا حذف کنی. مدت می‌تونه چند گزینه‌ی ثابت باشه (مثل ۳۰/۶۰/۹۰).\n4️⃣ «👥 گروه‌ها و زبان‌ها»: کاربر عادی، نماینده، نماینده سطح ۲ و هر زبان رو جدا روشن/خاموش کن.\n5️⃣ «🔎 فیلترها و تخفیف‌ها» (اختیاری): حداقل موجودی، گرد کردن، تخفیف پلکانی، تخفیف ویژه و پیشنهاد بسته‌ی ارزون‌تر.\n6️⃣ «👁 پیش‌نمایش»: صفحه‌ی مشتری رو همون‌طور که می‌بینه، برای هر زبان و گروه، نگاه کن.\n7️⃣ دکمه‌ی بالای همین صفحه رو بزن تا روشن بشه.\n\n<b>قیمت چطور حساب می‌شه؟</b>\nقیمت = حجم × قیمت هر گیگ + روز × قیمت هر روز\nبعد تخفیف پلکانی (روی قسمت حجم)، تخفیف ویژه (روی کل) و گرد کردن اعمال می‌شه. تخفیف حساب خود مشتری و کد تخفیف هم مثل همیشه توی فاکتور کم می‌شن.\n\n<b>فیلترها</b>\n👛 حداقل موجودی: مشتری با موجودی کمتر، به‌جای صفحه دکمه‌ی افزایش موجودی می‌گیره\n🔢 گرد کردن: قیمت به عدد رُند می‌رسه\n🎁 تخفیف پلکانی: مثلاً از ۵۰ گیگ به بالا ۱۰٪\n🔥 تخفیف ویژه: درصد تخفیف برای چند روز\n💡 پیشنهاد بسته‌ی ارزون‌تر: اگه یه بسته‌ی آماده همون‌قدر یا بیشتر رو ارزون‌تر بده، روی صفحه پیشنهاد می‌شه\n📊 آمار فروش: چند تا فروخته شده و پرفروش‌ترین انتخاب‌ها\n\n<b>متن و ظاهر</b>\nکپشن، دکمه‌ها، استیکر و تکه‌های متن برای هر زبان جدا: 🎨 شخصی‌سازی ← 🛒 پیام‌ها و ظاهر مراحل خرید ← 🧩 حجم دلخواه (یا دکمه‌ی «🎨 ظاهر و متن‌ها» همین‌جا).\n\n<b>پنل وب</b>\nهمه‌ی این تنظیمات توی پنل وب هم هست: منوی «حجم دلخواه».",
      'featureSettingsBtn' => '🧩 تنظیمات حجم دلخواه',
