➖➖➖➖➖➖➖➖➖➖
<b>🎁 هدیه به همه، مرحله به مرحله</b>
1️⃣ «📦 حجم اضافه کن» یا «⏰ زمان اضافه کن».
2️⃣ عدد ثابت برای همه، یا درصد از کل یا از باقی‌مونده‌ی هر اشتراک.
3️⃣ مقدارش رو بفرست.
4️⃣ کاربرهای کدوم پنل‌ها (هیچ‌کدوم یعنی همه).
5️⃣ خلاصه رو ببین و «🚀 شروع کن».
هر مرحله «🔙 برگشت» داره که می‌ره مرحله‌ی قبل، و هر چی انتخاب کردی بالای صفحه نوشته می‌شه.

<b>✏️ مقدار رو چطور بنویسم؟</b>
📦 حجم:
▫️ <code>5</code> یعنی 5 گیگ
▫️ <code>5.5</code> یعنی 5 گیگ و 500 مگابایت
▫️ <code>0.1</code> یعنی 100 مگابایت
⏰ زمان (عدد بعد از نقطه ساعته):
▫️ <code>1</code> یعنی 1 روز
▫️ <code>0.1</code> یعنی 1 ساعت
▫️ <code>2.12</code> یعنی 2 روز و 12 ساعت

<b>🔜 کمپین خرید</b>
از وقتی شروعش کنی تا چند ساعت، هر کی از ربات بخره هدیه می‌گیره. اول هدیه رو می‌پرسه، بعد مدتش رو.

<b>🎯 تنظیمات بیشتر</b>
فقط وقتی لازمه: فقط به یه زبان، فقط به خریدهای یه بازه، به تموم‌شده‌ها هم، به اکانت‌هایی که توی ربات نیستن هم، به کانفیگ‌های هدیه‌ی دعوت هم، یا بدون پیام به کاربر. هر چی عوض کنی، توی خلاصه یه خط ▫️ براش میاد.

<b>⚠️ کی چیزی نمی‌گیره؟</b>
⏱ اکانت ساعتی، 🧪 تست، ♾ نامحدود و 🎁 کانفیگی که با آوردن رفرال (هدیه‌ی دعوت) گرفته شده؛ اگه این آخری رو هم خواستی، از «🎯 تنظیمات بیشتر». ⏸ اکانتی که هنوز شروع نشده، زمانش روی طولش اضافه می‌شه و منتظر می‌مونه.

<b>📊 بعد از شروع</b>
یه پیام پیشرفت با «🚫 لغو» میاد؛ آخرش گزارش میاد که دقیقاً به چند نفر رسید. اگه پنل جواب نده، ربات هر اکانت رو تا ۳ بار امتحان می‌کنه؛ اگه باز هم نشد، زیر گزارش «🔁 دوباره امتحان کن» میاد که فقط همون‌ها رو دوباره امتحان می‌کنه.',
