4️⃣ خلاصه رو ببین و «🚀 شروع کن».
هر مرحله «🔙 برگشت» داره که می‌ره مرحله‌ی قبل، و هر چی انتخاب کردی بالای صفحه نوشته می‌شه.

<b>⚠️ چرا فقط ربکا؟</b>
محدودیت سرعت رو فقط پنل ربکا داره؛ پنل‌های دیگه این‌جا نشون داده نمی‌شن و دست نمی‌خورن.

<b>💡 محصول‌ها</b>
این فقط سرویس‌هایی رو که الان هستن عوض می‌کنه. محصولی که خودش محدودیت سرعت داره (🛍 ✏️ ویرایش محصول ← 🚀)، موقع تمدید سرعت خودش رو دوباره روی سرویس می‌ذاره.

