      'aboutBot' => '👨‍💼 <b>پنل مدیریت</b>

📖 <b>بخش‌های پنل</b>
<blockquote>📊 <b>آمار ربات:</b> <i>فروش، درآمد و کاربرها</i>
✏️ <b>مدیریت پنل:</b> <i>سرورها و تنظیماتشون</i>
