🤙 <b>بخش پشتیبانی:</b> <i>آیدی پشتیبانی و دپارتمان‌ها</i>
🛠 <b>قابلیت های پنل:</b> <i>گزینه‌های هر سرور</i>
⚙️ <b>تنظیمات عمومی:</b> <i>کانال، گزارش، ادمین‌ها، بکاپ و آپدیت</i>
💵 <b>رسید های تایید نشده:</b> <i>کارت‌به‌کارت‌های منتظر تایید</i>
🎨 <b>شخصی‌سازی پیام‌های ربات:</b> <i>متن و دکمه‌ها، برای هر زبان</i>
📬 <b>گزارش ربات:</b> <i>مشکل یا پیشنهاد به سازنده ربات</i></blockquote>

⌨️ <b>دستورهای سریع</b>
<blockquote>🏠 <b>باز کردن پنل:</b> ‎<code>/panel</code>
👤 <b>کاربر با آیدی:</b> ‎<code>/user 123456789</code>
👤 <b>کاربر با یوزرنیم:</b> ‎<code>/user @username</code>
🔎 <b>پیدا کردن سرویس:</b> ‎<code>/config نام_سرویس</code>
⏳ <b>تمدید سرویس:</b> ‎<code>/extend نام_سرویس</code>
🏬 <b>تنظیمات فروشگاه:</b> ‎<code>/shop</code>
💾 <b>بکاپ فوری:</b> ‎<code>/backup</code>
🔄 <b>آپدیت ربات:</b> ‎<code>/update</code></blockquote>
💡 <i>روی هر دستور بزنی کپی می‌شه؛ عدد یا نام رو عوض کن و بفرست.</i>
🔒 <i>بعضی بخش‌ها و دستورها فقط برای ادمین با دسترسی کامله.</i>',
