      'ask_grace' => "⌛ <b>مهلت شارژ</b> — {lang}\n\nوقتی موجودی تموم شد، سرویس غیرفعال می‌شه. اگه کاربر تا این مدت شارژ کنه خودکار روشن می‌شه، وگرنه از پنل و «🛍 سرویس‌های من» حذف می‌شه (دو ساعت قبلش یه بار دیگه خبرش می‌کنیم).\nعدد به ساعت بفرست (مثلاً <code>48</code>)، یا با واحد: <code>2 روز</code>.\n<code>0</code> = بدون مهلت (فوری حذف).",
