    'bgGuide' => 'راهنما',
    'bgGuideText' => '1. «نوع کار» رو انتخاب کن: هدیه به اشتراک‌هایی که الان هستن، یا کمپین خرید (به هر خریدی از وقت شروع تا چند ساعت).
2. حجم یا زمان رو انتخاب کن، بعد «روش حساب» (عدد ثابت، یا درصد از کل یا از باقی‌مونده‌ی هر اشتراک)، بعد مقدارش و پنل‌ها:
• حجم: 5 یعنی 5 گیگ، 5.5 یعنی 5 گیگ و 500 مگابایت، 0.1 یعنی 100 مگابایت
• زمان: 1 یعنی 1 روز، 0.1 یعنی 1 ساعت، 2.12 یعنی 2 روز و 12 ساعت (عدد بعد از نقطه ساعته، تا 23)
3. «تعداد رو ببین» رو بزن تا ببینی حدوداً به چند اشتراک می‌رسه، بعد «شروع کن».
«تنظیمات بیشتر» اختیاریه: زبان، زمان خرید، وضعیت حساب، اکانت‌هایی که توی ربات نیستن، کانفیگ‌های هدیه‌ی دعوت و پیام به کاربر.
اکانت ساعتی، تست، نامحدود و کانفیگی که با آوردن رفرال گرفته شده چیزی نمی‌گیرن (این آخری رو از «تنظیمات بیشتر» می‌شه روشن کرد). اکانتی که هنوز شروع نشده، زمانش روی طولش اضافه می‌شه و منتظر می‌مونه.
پیشرفتش همین‌جا و توی ربات میاد؛ گزارش آخرش، با عدد دقیق، توی ربات میاد. اکانتی که پنلش جواب نده تا ۳ بار امتحان می‌شه؛ اگه باز هم نشد، توی «کارهای قبلی» دکمه‌ی «دوباره برای خطاها» میاد.',
